package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem string // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct int64 // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec
var inputDone bool

var inputLines []string
var inputIdx int

func padLine(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	totalDigits := intDigits + scale
	modulus := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	unscaled := v.Shift(int32(scale)).Truncate(0)
	isNeg := unscaled.IsNegative()
	if isNeg {
		unscaled = unscaled.Neg()
	}
	// unscaled % modulus
	div := unscaled.Div(modulus).Truncate(0)
	rem := unscaled.Sub(div.Mul(modulus))
	if isNeg {
		rem = rem.Neg()
	}
	return rem.Shift(int32(-scale))
}

func formatEdited(v decimal.Decimal, picture string) string {
	parts := strings.Split(picture, ".")
	intPic := parts[0]
	fracPic := ""
	if len(parts) > 1 {
		fracPic = parts[1]
	}
	fracDigits := len(fracPic)
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	isNeg := v.IsNegative()
	if isNeg {
		v = v.Neg()
	}
	// ensure exactly fracDigits after decimal
	s := v.StringFixed(int32(fracDigits))
	s = strings.TrimPrefix(s, "-")
	dotIdx := strings.Index(s, ".")
	var intPartStr, fracPartStr string
	if dotIdx >= 0 {
		intPartStr = s[:dotIdx]
		fracPartStr = s[dotIdx+1:]
	} else {
		intPartStr = s
		if fracDigits > 0 {
			fracPartStr = strings.Repeat("0", fracDigits)
		}
	}
	if fracDigits > 0 {
		if len(fracPartStr) < fracDigits {
			fracPartStr = fracPartStr + strings.Repeat("0", fracDigits-len(fracPartStr))
		} else if len(fracPartStr) > fracDigits {
			fracPartStr = fracPartStr[:fracDigits]
		}
	}
	if len(intPartStr) > intDigits {
		intPartStr = intPartStr[len(intPartStr)-intDigits:]
	}
	if len(intPartStr) < intDigits {
		intPartStr = strings.Repeat("0", intDigits-len(intPartStr)) + intPartStr
	}
	var intFormatted strings.Builder
	digitIdx := 0
	suppress := true
	for _, ch := range intPic {
		if ch == ',' {
			if suppress {
				intFormatted.WriteByte(' ')
			} else {
				intFormatted.WriteByte(',')
			}
		} else if ch == 'Z' || ch == '9' {
			d := intPartStr[digitIdx]
			digitIdx++
			if suppress {
				if ch == 'Z' && d == '0' {
					intFormatted.WriteByte(' ')
				} else {
					intFormatted.WriteByte(d)
					suppress = false
				}
			} else {
				intFormatted.WriteByte(d)
			}
		} else {
			intFormatted.WriteByte(byte(ch))
		}
	}
	result := intFormatted.String()
	if fracDigits > 0 {
		result = result + "." + fracPartStr
	}
	return result
}

func formatUneditedInt(val int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v := val % mod
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func parseDiscRec(line string) DiscRec {
	line = padLine(line, 15)
	item := line[0:6]
	priceRaw := line[6:13]
	pctRaw := line[13:15]

	// price: 7 digits implied 2 decimals
	priceRawTrim := strings.TrimSpace(priceRaw)
	var price decimal.Decimal
	if priceRawTrim == "" {
		price = decimal.New(0, -2)
	} else {
		// priceRaw should be digits only; parse as integer
		// handle leading spaces/zero
		// Use decimal from string then shift
		// Remove spaces
		t := strings.TrimSpace(priceRaw)
		// if contains non-digit, treat as 0
		// parse with decimal
		if t == "" {
			price = decimal.New(0, -2)
		} else {
			// ensure all digits
			d, err := decimal.NewFromString(t)
			if err != nil {
				// fallback parse int
				var n int64
				fmt.Sscanf(t, "%d", &n)
				d = decimal.NewFromInt(n)
			}
			// d is integer of digits, need to shift -2
			price = d.Shift(-2)
		}
	}
	pctTrim := strings.TrimSpace(pctRaw)
	var pct int64
	if pctTrim != "" {
		var n int64
		fmt.Sscanf(pctTrim, "%d", &n)
		pct = n
		// keep low-order 2 digits for storage
		pct = pct % 100
		if pct < 0 {
			pct = -pct
		}
	}
	return DiscRec{DrItem: item, DrPrice: price, DrPct: pct}
}

// paragraph functions

func ReadPara() {
	if inputIdx >= len(inputLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	discRec = parseDiscRec(line)
}

func ProcessPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	raw := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	rounded := raw.Round(2)
	WsDiscount = storeDecimal(rounded, 5, 2)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	netRaw := discRec.DrPrice.Sub(WsDiscount).Truncate(2)
	WsNet = storeDecimal(netRaw, 5, 2)
	// ADD WS-NET TO WS-TOTAL-NET
	newTotal := WsTotalNet.Add(WsNet).Truncate(2)
	WsTotalNet = storeDecimal(newTotal, 8, 2)
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	pctStr := formatUneditedInt(discRec.DrPct, 2)
	line := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprint(os.Stdout, line+"\n")
	// PERFORM READ-PARA
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprint(os.Stdout, line+"\n")
}

func MainPara() {
	// OPEN INPUT DISC-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// preserve trailing spaces: Scanner strips newline but keeps spaces; need to allow long lines
	// increase buffer
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	inputLines = []string{}
	for scanner.Scan() {
		// scanner.Text() returns line without newline; keep as is
		// Need to handle \r for Windows line endings: scanner already strips, but we also strip \r if present
		txt := scanner.Text()
		// Scanner's Split already handles \r, but just in case
		inputLines = append(inputLines, txt)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	inputIdx = 0
	WsEofFlag = "N"
	inputDone = false
	WsDiscount = decimal.New(0, -2)
	WsNet = decimal.New(0, -2)
	WsTotalNet = decimal.New(0, -2)
	WsCount = 0

	ReadPara()
	for !inputDone {
		ProcessPara()
	}
	// CLOSE DISC-FILE already deferred
	SummaryPara()
}

func main() {
	MainPara()
}
